"""Add same-run cost attribution and explicit full-run correctness limitations."""
import json,csv,sys
from pathlib import Path
R=Path(__file__).resolve().parents[2];E=R/'output/evaluation';rid=sys.argv[1];D=E/'diagnostics'/rid;P=E/'results/accuracy'/rid
m=json.loads((D/'manifest.json').read_text());n=json.loads((P/'manifest.json').read_text());runs={r['backend']:r for r in n['runs']};a,b=runs['cuda'],runs['rt-custom'];ta,tb=a['totals'],b['totals'];setup=b['rt_setup_seconds']
with (P/'rt-custom_differences.tsv').open() as f:diff=list(csv.DictReader(f,delimiter='\t'))
(D/'result_discrepancies.json').write_text(json.dumps(diff,indent=2,ensure_ascii=False))
m['validation_status']='performance_measured_matching_not_equivalent' if diff else 'performance_measured_retained_outputs_equal';m['candidate_counts_equal']=a['totals']['candidates']==b['totals']['candidates'];m['all_batches_cache_disabled']=all(int(x['cached_ions'])==0 and int(x['cache_charge_stride'])==0 for r in n['runs'] for x in r['batches']);m['mismatch_scan_ids']=sorted({d['scan_id'] for d in diff},key=int);(D/'manifest.json').write_text(json.dumps(m,indent=2))
lines=['','## 全量验证结论与限制','','本次确实完成 Marine 全 FASTA、X2 全部 46,862 张谱图；每后端生成 464,495,485 条肽段，5,210,796,545 个候选关联，39 批。多前体 reader 开启，所有批次缓存均关闭。两个后端生成肽段和逐批候选计数一致，但本轮没有逐候选/逐查询指纹观察器。','',f"融合评分节省 {ta['fused_device_seconds']-tb['fused_device_seconds']:.3f} s，RT setup 新增 {setup:.3f} s，完整 GPU 服务仍节省 {ta['gpu_service_seconds']-tb['gpu_service_seconds']:.3f} s，完整 MVH search 节省 {float(a['summary']['search_seconds'])-float(b['summary']['search_seconds']):.3f} s。相比此前小负载，本次评分收益足以覆盖一次性结构准备成本；这不证明增加 scan 或数据库时该比率一直保持。",'','### 结果尚未完全等价','','45,719 个有结果谱图的 Top-1 肽段、charge 和分数全部一致，但全部保留列表中有 2 个谱图结果组不同，PSM SHA256 不同。','- scan 33520：保留候选集合有 2 条 CUDA 独有、2 条 RT-custom 独有。','- scan 36940：共同候选 `[LTRETALSVN!DLILPM~FVIEGTSQSEAVASMPGVNR]`、charge 4，CUDA MVH 30.715225219726562，RT-custom 34.288776874542236，rank 14→4。', '差异不能据已有小子集审计直接归因为 float 容差；当前需要针对这两个 scan 做受控峰级审计。速度数字是实际完成运行的观察值，不能称为严格等价实现的最终性能结论，也不代表生物准确率/FDR 已验证。','', '### 同次运行的开销分解','','| 阶段 | CUDA s | RT-custom s |','|---|---:|---:|']
for label,x,y in [('融合评分',ta['fused_device_seconds'],tb['fused_device_seconds']),('RT setup',0,setup),('其余 GPU 服务',ta['gpu_service_seconds']-ta['fused_device_seconds'],tb['gpu_service_seconds']-tb['fused_device_seconds']-setup),('完整 GPU 服务',ta['gpu_service_seconds'],tb['gpu_service_seconds']),('host packing',ta['pack_seconds'],tb['pack_seconds']),('host 结果恢复',ta['replay_verify_seconds'],tb['replay_verify_seconds'])]:lines.append(f'| {label} | {x:.3f} | {y:.3f} |')
lines+=['','RT setup 只记录一次：pipeline 0.099 s、几何准备 0.072 s、sizing 0.022 s、构建与等待 5.538 s。RT retention 为 7.869 s，CUDA 4.457 s，尚未将差异归因于某个 kernel 或调度因素。','单次、顺序运行、无预热、GPU 时钟未锁定，系统负载/频率随运行可能变化；必须保留这些限制。未恢复其他大型实验，也未改动核心匹配算法。','']
with (D/'report.md').open('a') as f:f.write('\n'.join(lines))
print(json.dumps({k:m[k] for k in ('validation_status','candidate_counts_equal','all_batches_cache_disabled','mismatch_scan_ids')},indent=2))
